'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16M17 4v16M3 9h4m-4 6h4m10-6h4m-4 6h4"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3Z"/>',queue:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',book:'<path d="M12 5v15M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',arrow:'<path d="m8 4 8 8-8 8"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3Z"/>',move:'<path d="M12 2v20M2 12h20m-14-6 4-4 4 4M8 18l4 4 4-4M6 8l-4 4 4 4m12-8 4 4-4 4"/>',undo:'<path d="M3 11h11a6 6 0 0 1 0 12M3 11l6-6m-6 6 6 6" transform="translate(0 -3)"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;}
const scenes=[{name:'雨夜来信',desc:'她在旧书店门口发现了一封写给未来的信。',camera:'全景 · 缓慢推进',duration:5,pos:'center'},{name:'熟悉的字迹',desc:'信封上，是十年前母亲留下的字迹。',camera:'特写 · 固定镜头',duration:5,pos:'36% center'},{name:'重返旧书店',desc:'她推开门，熟悉的铃声打破了沉默。',camera:'中景 · 跟随',duration:5,pos:'left center'},{name:'灯光下的答案',desc:'原来，总有人在时光的另一端等她。',camera:'近景 · 缓慢拉远',duration:5,pos:'right center'}];
const defaults=()=>({version:1,view:'commerce',style:0,ratio:'1:1',count:'4',prompt:'为植物精华液制作一组自然、克制的春日上新素材。保留瓶身、标签和商品比例；画面留出标题空间。',title:'让自然，\n唤醒每一天',story:'一个雨夜，林夏在旧书店门口收到一封来自十年前的信。信封上的字迹属于她已故的母亲。请用温暖、克制的方式讲述她重新找到生活勇气的故事。',storyTitle:'最后一封信',color:'#283d31',textSize:29,textX:8,textY:9,selected:0,shot:0,tasks:[],results:[],scriptReady:false,asset:null,assets:{},assetId:null,confirmedScript:null,assetName:'植物精华液 · 预置场景图',characters:'林夏，28岁，米色风衣，黑色齐肩发；整部短剧保持同一造型。',savedAt:Date.now()});
let state;let storageAvailable=true;try{const saved=JSON.parse(localStorage.getItem('muse-studio-v1'));state=saved?.version===1?{...defaults(),...saved}:defaults();}catch{state=defaults();storageAvailable=false;}
if(state.asset){state.assets['legacy-upload']={source:state.asset,name:state.assetName};state.assetId='legacy-upload';state.asset=null;}
const scriptKey=()=>JSON.stringify([state.storyTitle,state.story,state.characters]);
if(!state.confirmedScript||state.confirmedScript!==scriptKey())state.scriptReady=false;
function currentImage(){return state.assets[state.assetId]?.source||'assets/product.png';}
function taskImage(t){return state.assets[t.snapshot.assetId]?.source||(t.scenario==='commerce'?'assets/product.png':'assets/story.png');}
state.tasks.forEach(t=>{if(t.status==='running'){t.status='interrupted';t.error='上次页面关闭导致演示任务中断，可从快照重试。';}});
let failNext=false,toastTimer,playing=false,playTimer,history=[];
function persist(){try{state.savedAt=Date.now();localStorage.setItem('muse-studio-v1',JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;}const note=$('#save-state');if(note)note.textContent=storageAvailable?'已自动保存':'保存失败，请导出项目备份';}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function remember(){history.push({title:state.title,textSize:state.textSize,color:state.color,textX:state.textX,textY:state.textY,ratio:state.ratio});if(history.length>20)history.shift();}
const activeCount=()=>state.tasks.filter(t=>['running','queued'].includes(t.status)).length;
function render(){const view=state.view;const names={commerce:'电商素材',drama:'短剧分镜',assets:'素材库',tasks:'任务中心',docs:'方案文档'};$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">✳</div><div class="wordmark">MUSE<small>STUDIO</small></div></div><div class="workspace"><div class="workspace-icon">M</div><span>我的创作空间<small>个人工作区 · 面试展示版</small></span></div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="工作区导航">${[['commerce','grid','电商素材'],['drama','film','短剧分镜'],['assets','folder','素材库'],['tasks','queue','任务中心'],['docs','book','方案文档']].map(([key,i,label])=>`<button data-nav="${key}" class="${view===key?'active':''}" aria-label="${label}">${icon(i)}<span class="nav-text">${label}</span>${key==='tasks'?`<span class="count">${activeCount()}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="cloud-card"><span class="dot"></span>线上模型方案<p>DeepSeek · 创意与脚本<br>视觉素材为预置演示结果</p></div><div class="user"><div class="avatar">M</div><div>Muse Creator<small>INTERVIEW EDITION</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">创作空间 <span style="margin:0 10px;color:#555861">/</span> <strong>${names[view]}</strong></div><div class="top-actions"><span class="chip green">● 交互演示模式</span><a class="btn small shareLink" href="integration-preview.html">集成实测 ↗</a><button class="btn small" data-action="guide">演示指南 ↗</button><button class="icon-btn" data-action="settings" aria-label="查看模型方案">${icon('spark')}</button></div></header><div class="content">${view==='commerce'?commerce():view==='drama'?drama():view==='tasks'?tasksView():view==='assets'?assetsView():docsView()}</div></main></div>`;bind();}
function heading(eyebrow,title,sub,right=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="right">${right}</div></div>`;}
function switches(view){return `<div class="scenario-switch"><button data-nav="commerce" class="${view==='commerce'?'active':''}">电商素材</button><button data-nav="drama" class="${view==='drama'?'active':''}">短剧分镜</button></div>`;}
function footer(){return `<div class="footer-note"><span>✳ 预置视觉素材演示 · 未调用线上模型 · 生成进度与耗时均为模拟</span><span id="save-state">${storageAvailable?'已自动保存':'本机存储不可用，请导出备份'} · 本浏览器保存</span></div>`;}
function commerce(){return `${heading('IMAGE WORKSPACE','把一件商品，变成一组好创意。','从商品素材到场景图，让创意、编辑与批量交付在同一张画布发生。',switches('commerce'))}<div class="studio-layout"><section class="config" aria-label="电商生成设置"><div class="section-title"><span><span class="step">01</span>创作设置</span><small>IMAGE</small></div><div class="field"><label>商品素材</label><button class="upload" data-action="upload"><img src="${currentImage()}" alt="商品素材"><div><strong>${esc(state.assetName)}</strong><small>点击替换 · PNG / JPG / WebP<br>本地预览，不上传至模型</small></div></button><input id="file-input" type="file" accept="image/png,image/jpeg,image/webp" hidden></div><div class="field"><div class="label-row"><label for="prompt">创作要求</label><button class="text-btn" data-action="optimize">✧ 优化描述</button></div><textarea id="prompt">${esc(state.prompt)}</textarea></div><div class="field"><label>视觉风格</label><div class="style-options">${['晨光植物','奶油极简','暖调胶片'].map((s,i)=>`<button data-style="${i}" class="style-option ${state.style===i?'selected':''}" aria-label="${s}"><img src="assets/product.png" style="filter:${['none','saturate(.45) brightness(1.1)','sepia(.35)'][i]};object-position:${['center','right','left'][i]}" alt=""><span>${s}</span></button>`).join('')}</div><p class="hint">风格切换为预置色调预览</p></div><div class="field"><label>画布比例</label><div class="pills">${['1:1','3:4','9:16'].map(r=>`<button data-ratio="${r}" class="${state.ratio===r?'selected':''}">${r}</button>`).join('')}</div></div><div class="field"><label for="count">生成数量</label><select id="count"><option value="2" ${state.count==='2'?'selected':''}>2 张 · 快速探索</option><option value="4" ${state.count==='4'?'selected':''}>4 张 · 多方向探索</option></select></div><div class="generate-wrap"><div class="divider"></div><button class="btn primary" style="width:100%" data-action="generate-commerce">✧ 生成 ${state.count} 张素材</button><p class="hint">保留商品信息，先选方向再精修。<br>此操作创建模拟任务，不产生模型费用。</p></div></section><section class="canvas-area"><div class="canvas-toolbar"><div class="tools"><button class="icon-btn" aria-label="移动标题" data-action="move-info">${icon('move')}</button><button class="icon-btn" aria-label="撤销编辑" data-action="undo">${icon('undo')}</button><span style="padding:7px">画布 / 创意 ${String(state.selected+1).padStart(2,'0')}</span></div><button class="text-btn" data-action="export-commerce">导出素材 ${icon('download')}</button></div><div class="canvas-stage"><div id="artboard" class="artboard" data-ratio="${state.ratio}"><img src="${currentImage()}" style="filter:${['none','saturate(.45) brightness(1.1)','sepia(.35)'][state.style]}" alt="商品场景图预置演示"><div class="poster-copy" id="poster-copy" style="left:${state.textX}%;top:${state.textY}%;color:${state.color}"><span class="mini">MUSE · BOTANICAL</span><h2 id="poster-title" style="font-size:${state.textSize}px">${esc(state.title)}</h2><span class="desc">植物精华液 / 春日限定灵感</span><div class="selection"></div></div></div></div><div class="canvas-foot"><span>拖动标题调整位置 · 右侧编辑文字</span><span>预置素材 · ${state.ratio}</span></div></section><aside class="inspector"><div class="inspector-title">画布属性 <span style="float:right;color:#7e818a">☷</span></div><div><div class="mini-title">图层</div><div class="layers"><div class="layer on">T &nbsp;主标题 <small>可拖动</small></div><div class="layer">▧ &nbsp;商品与场景 <small>合成底图</small></div><div class="layer">▱ &nbsp;画布背景 <small>锁定</small></div></div><div class="field"><label for="poster-text">标题文案</label><textarea id="poster-text" style="min-height:80px">${esc(state.title)}</textarea></div></div><div><div class="field"><label for="text-size">字号 <span id="size-value" style="float:right">${state.textSize} px</span></label><input id="text-size" type="range" min="16" max="44" value="${state.textSize}" style="width:100%;accent-color:#ceee92"></div><div class="field"><label>文字颜色</label><div class="swatches">${['#283d31','#eee9dd','#3a2b26'].map(c=>`<button class="swatch" style="background:${c};${state.color===c?'outline:1px solid #ceee92':''}" data-color="${c}" aria-label="文字颜色 ${c}"></button>`).join('')}</div></div><div class="field"><label>输出尺寸</label><div class="dimension"><span>W <b>${size()[0]}</b></span><span>H <b>${size()[1]}</b></span></div></div></div><div class="tip-card"><strong>✧ 商品保真优先</strong>当前底图为预置合成图。真实方案锁定商品层，优先生成背景，避免商品标签与包装被重绘。<div class="divider" style="margin:10px 0"></div>标题为独立图层，可移动与修改。</div></aside></div><div class="bottom-strip"><h2>创意探索 <span style="margin-left:8px;color:#727680;font-size:10px">PRESET COLLECTION</span></h2><span id="commerce-result-count">${state.results.filter(x=>x.scenario==='commerce').length} 张模拟任务结果</span></div><div class="results-grid">${[0,1,2].map(i=>`<button class="result ${state.selected===i?'selected':''}" data-result="${i}"><div class="visual"><img src="assets/product.png" style="filter:${['none','saturate(.45) brightness(1.1)','sepia(.35)'][i]};object-position:${['center','top','bottom'][i]}" alt="预置创意 ${i+1}"><span class="badge">${i===state.selected?'✓ 已应用':'预置素材'}</span></div><div class="result-info"><strong>${['晨光里的植物力','留白，自有力量','温暖的日常'][i]}</strong><small>创意 0${i+1}</small></div></button>`).join('')}<button class="result empty" data-action="generate-commerce"><div><span>＋</span>探索更多可能<br><small>创建一组模拟任务</small></div></button></div>${footer()}`;}
function size(){return state.ratio==='3:4'?[1080,1440]:state.ratio==='9:16'?[1080,1920]:[1080,1080];}
function drama(){const s=scenes[state.shot];return `${heading('STORY WORKSPACE','让一个故事，拥有自己的镜头。','从灵感到分镜，锁定角色设定，让每个镜头都服务于同一个故事。',switches('drama'))}<div class="studio-layout drama"><section class="config" aria-label="短剧生成设置"><div class="section-title"><span><span class="step">01</span>故事设定</span><small>STORY</small></div><div class="field"><label for="story-title">短剧名称</label><input class="input" id="story-title" maxlength="60" value="${esc(state.storyTitle)}"></div><div class="field"><label for="story">故事梗概</label><textarea id="story" style="min-height:132px">${esc(state.story)}</textarea></div><div class="field"><label for="characters">角色设定 · 全片共享</label><textarea id="characters" style="min-height:85px">${esc(state.characters)}</textarea><p class="hint">故事或角色变更后需重新确认；预置剧照不随输入变化。</p></div><div class="field"><label>成片规划</label><div class="pills"><button class="selected" data-action="duration-info">4 镜头 · 20 秒</button><button class="selected" data-action="duration-info">16:9</button></div></div><div class="generate-wrap"><div class="divider"></div><button class="btn primary" style="width:100%" data-action="generate-script">✧ ${state.scriptReady?'重新生成分镜脚本':'生成分镜脚本'}</button><p class="hint">先确认脚本，再批量生成画面。<br>当前展示示例脚本，不调用 DeepSeek。</p><div class="compact-drama-actions"><button class="btn" data-action="generate-shot" ${!state.scriptReady?'disabled':''}>仅生成当前镜头</button><button class="btn primary" data-action="generate-drama" ${!state.scriptReady?'disabled':''}>批量生成 4 个镜头</button></div></div></section><section class="canvas-area"><div class="canvas-toolbar"><span><span id="drama-project-title">分镜预览 / ${esc(state.storyTitle)}</span></span><button class="text-btn" data-action="export-drama">导出分镜包 ↗</button></div><div class="canvas-stage"><div class="drama-stage-label"><span>SHOT ${String(state.shot+1).padStart(2,'0')} <span style="margin-left:10px;color:#777e88">${s.camera}</span></span><span class="chip purple">预置剧照</span></div><div class="storyboard-view"><img src="assets/story.png" style="object-position:${s.pos};${state.shot===1?'transform:scale(1.3)':''}" alt="虚构短剧预置剧照"><div class="film-overlay"></div><button class="preview-play" data-action="preview" aria-label="预览分镜序列">▶</button><div class="shot-caption"><small><span id="drama-caption-title">${esc(state.storyTitle)}</span> · ${s.duration} SECONDS</small>${s.desc}</div></div><div class="shot-list">${scenes.map((s,i)=>`<button class="shot ${state.shot===i?'active':''}" data-shot="${i}"><img src="assets/story.png" style="object-position:${s.pos}" alt=""><div>${String(i+1).padStart(2,'0')} ${s.name}<small>${s.duration}s · ${s.camera.split(' · ')[0]}</small></div></button>`).join('')}</div><div class="story-timeline">${scenes.map((s,i)=>`<button class="timeline-block ${state.shot===i?'active':''}" data-shot="${i}" aria-label="选择镜头 ${i+1}">镜头 ${i+1} · 5s</button>`).join('')}</div></div><div class="canvas-foot"><span>${state.scriptReady?'✓ 分镜脚本已确认':'示例分镜 · 请先生成并确认脚本'}</span><span>00:${String(state.shot*5).padStart(2,'0')} / 00:20</span></div></section><aside class="inspector"><div class="inspector-title">分镜详情</div><div><div class="field"><label>当前镜头</label><div class="mini-title">${s.name}</div><p class="hint">${s.desc}</p></div><div class="field"><label>镜头语言</label><div class="dimension"><span style="width:100%">${s.camera}</span></div></div><div class="field"><label>角色一致性</label><span class="chip green">◈ 共享角色设定</span><p class="hint"><span id="drama-characters">${esc(state.characters)}</span><br>当前仅展示预置角色剧照，不随文字改写。</p></div></div><div><button class="btn" style="width:100%" data-action="generate-shot" ${!state.scriptReady?'disabled':''}>仅生成当前镜头</button><button class="btn primary" style="width:100%;margin-top:10px" data-action="generate-drama" ${!state.scriptReady?'disabled':''}>批量生成 4 个镜头</button><p class="hint">创建独立镜头任务，可单镜头重试。</p></div><div class="tip-card"><strong>✧ 先确认，再花费</strong>真实方案会在视觉生成前展示费用预估。当前只创建模拟任务，序列预览为静帧轮播，不代表真实视频。</div></aside></div><div class="bottom-strip"><h2>故事的四个瞬间</h2><span>角色设定 → 脚本确认 → 分镜任务 → 导出</span></div><div class="results-grid">${scenes.map((s,i)=>`<button class="result ${state.shot===i?'selected':''}" data-shot="${i}"><div class="visual"><img src="assets/story.png" style="object-position:${s.pos};transform:scale(${i===1?1.35:1})" alt="${s.name}示例"><span class="badge">SHOT 0${i+1} · 预置</span></div><div class="result-info"><strong>${s.name}</strong><small>${s.duration}s</small></div></button>`).join('')}</div>${footer()}`;}
const statuses={queued:'排队中',running:'生成中',completed:'已完成',failed:'生成失败',cancelled:'已取消',interrupted:'已中断'};
function tasksView(){
  return `${heading('TASK ORCHESTRATION','每一个创意，都有迹可循。','最多两个模拟任务同时运行；编辑与生成互不阻塞，失败仅重试对应任务。',`<button class="btn" data-action="failure-demo">模拟一次失败</button><button class="btn primary" data-nav="commerce">＋ 创建任务</button>`)}<div class="stats"><div class="stat"><span>正在生成 / 并发上限</span><strong><b id="running-count" style="font-weight:500">${state.tasks.filter(t=>t.status==='running').length}</b><span style="font-size:15px"> / 2</span></strong></div><div class="stat"><span>等待调度</span><strong id="queued-count">${state.tasks.filter(t=>t.status==='queued').length}</strong></div><div class="stat"><span>已完成任务</span><strong id="completed-count">${state.tasks.filter(t=>t.status==='completed').length}</strong></div></div><div class="notice">演示任务在本浏览器计时运行。刷新后，运行中的任务标为“已中断”，已完成结果与编辑内容保留；重试使用提交时的设置快照。${failNext?' <b>下一项开始运行的任务将模拟失败。</b>':''}</div><div class="task-list">${state.tasks.length?state.tasks.slice().reverse().map(t=>`<article class="task-card" data-task-id="${t.id}" data-status="${t.status}"><div class="task-icon">${t.scenario==='commerce'?'▧':'▷'}</div><div class="task-content"><h3>${esc(t.name)} <span class="status ${t.status}" style="margin-left:10px">${statuses[t.status]}</span></h3><p>${esc(t.snapshot.label)} · 提交 ${new Date(t.createdAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})} · 尝试 ${t.attempt||1} 次</p><p class="error ${t.error?'':'hidden'}">${esc(t.error||'')}</p><div class="progress ${t.status==='running'?'':'hidden'}"><i style="width:${t.progress}%"></i></div></div><div class="task-actions">${taskActions(t)}</div></article>`).join(''):'<div class="empty-panel">还没有创作任务。<br>从电商素材或短剧分镜开始，任务会自动出现在这里。</div>'}</div>${footer()}`;
}
function assetsView(){return `${heading('ASSET LIBRARY','把好灵感，留在创作空间。','共享素材贯穿两个场景，任务结果与来源信息一起保存。',`<button class="btn" data-action="backup">导出项目备份</button>`)}<div class="asset-grid" id="asset-grid"><article class="asset-card"><img src="${currentImage()}" alt="当前商品素材"><div class="body"><h3>${esc(state.assetName)}</h3><p>${state.assetId?'用户本地上传 · 未发送到模型':'预置商品场景图 · 原型演示专用'}</p><div class="inline-tags"><span class="tag">电商素材</span><button class="text-btn" data-nav="commerce">进入工作台 ↗</button></div></div></article><article class="asset-card"><img src="assets/story.png" alt="预置虚构剧照"><div class="body"><h3>最后一封信 · 预置概念剧照</h3><p>预置虚构角色，不随角色文本变化</p><div class="inline-tags"><span class="tag">短剧分镜</span><button class="text-btn" data-nav="drama">进入工作台 ↗</button></div></div></article>${state.results.map(resultAssetCard).join('')}</div>${footer()}`;}
function docsView(){return `${heading('PRODUCT THINKING','从可用原型，到可信的产品方案。','三个文档共享同一套用户、模型和任务架构；数据目标与验证结果分开表达。')}<div class="asset-grid">${[['01','模型选型与评估方案','DeepSeek 的职责与边界、视觉模型候选、评测方法和成本取舍。','01-模型选型与评估方案.md'],['02','场景与用户说明','电商与短剧的核心任务、协作流程、MVP 模块与验收条件。','02-场景与用户说明.md'],['03','产品策略与技术方案','产品优先级、线上架构、任务状态机、并发与恢复机制。','03-产品策略与技术方案.md']].map(([n,title,desc,file])=>`<article class="asset-card"><div class="body" style="padding:26px"><div class="eyebrow">DOCUMENT ${n}</div><h3 style="font-size:18px;line-height:1.6;margin-top:20px">${title}</h3><p style="min-height:65px;margin:18px 0">${desc}</p><a class="btn" href="docs/${file}" download>下载 Markdown ↓</a></div></article>`).join('')}</div><div class="notice" style="margin-top:24px">当前网页为免费交互原型，使用预置素材与模拟任务；仓库另含已接入真实 DeepSeek、Fabric.js 和 FFmpeg 的集成版源码，可在自己的服务端运行。点击顶部「集成实测」查看实际截图与视频。</div><button class="btn" data-action="guide">查看 5 分钟演示路线</button>${footer()}`;}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.view=b.dataset.nav;persist();render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{state.style=+b.dataset.style;state.selected=state.style;persist();render();});document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>{remember();state.ratio=b.dataset.ratio;persist();render();});document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.result;state.style=state.selected;persist();render();});document.querySelectorAll('[data-shot]').forEach(b=>b.onclick=()=>{state.shot=+b.dataset.shot;persist();render();});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{remember();state.color=b.dataset.color;persist();render();});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.cancel);if(['queued','running'].includes(t.status)){t.status='cancelled';t.error='已取消模拟任务，保留提交快照。';persist();render();}});document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.retry);if(activeCount()>=20)return toast('待处理任务已达上限，请先完成或取消部分任务');t.status='queued';t.progress=0;t.attempt=(t.attempt||1)+1;t.fail=false;delete t.error;persist();render();toast('已使用原任务快照加入重试队列');});document.querySelectorAll('[data-open-task]').forEach(b=>b.onclick=()=>showTaskResult(state.tasks.find(t=>t.id===b.dataset.openTask)));document.querySelectorAll('[data-snapshot]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.snapshot);modal('提交时的设置快照',`<p>重试复用此快照；工作台后续编辑不会改变它。</p><pre style="white-space:pre-wrap;font-size:11px;color:#cbd1bf;line-height:1.8">${esc(JSON.stringify(t.snapshot,null,2))}</pre>`);});for(const [id,key] of [['prompt','prompt'],['story','story'],['story-title','storyTitle'],['characters','characters'],['count','count']]){const el=$('#'+id);if(el)el.oninput=()=>{state[key]=el.value;if(['story','story-title','characters'].includes(id))updateStoryInput();persist();if(id==='count'){const b=$('[data-action="generate-commerce"]');b.textContent=`✧ 生成 ${state.count} 张素材`;}};}if($('#poster-text')){$('#poster-text').onfocus=remember;$('#poster-text').oninput=e=>{state.title=e.target.value;$('#poster-title').textContent=state.title;persist();};}if($('#text-size')){$('#text-size').onpointerdown=remember;$('#text-size').oninput=e=>{state.textSize=+e.target.value;$('#poster-title').style.fontSize=state.textSize+'px';$('#size-value').textContent=state.textSize+' px';persist();};}if($('#file-input'))$('#file-input').onchange=uploadFile;const text=$('#poster-copy');if(text){text.onpointerdown=e=>{if(e.button!==0)return;remember();const rect=$('#artboard').getBoundingClientRect();const dx=e.clientX,dy=e.clientY,sx=state.textX,sy=state.textY;text.setPointerCapture(e.pointerId);text.onpointermove=ev=>{state.textX=Math.max(0,Math.min(50,sx+(ev.clientX-dx)/rect.width*100));state.textY=Math.max(0,Math.min(80,sy+(ev.clientY-dy)/rect.height*100));text.style.left=state.textX+'%';text.style.top=state.textY+'%';};text.onpointerup=()=>{text.onpointermove=null;persist();};};}}
function action(a){if(a==='generate-commerce'){if(!state.prompt.trim())return toast('请先填写创作要求');enqueue('commerce',+state.count);}else if(a==='generate-script'){if(!state.storyTitle.trim()||!state.story.trim()||!state.characters.trim())return toast('请先补全短剧名称、故事梗概与角色设定');modal('确认分镜脚本',`<p>以下为《${esc(state.storyTitle)}》的示例四镜头脚本。梗概与角色设定会保存在任务快照中；本原型没有调用 DeepSeek，示例剧情不会随输入自动改写。</p>${scenes.map((s,i)=>`<div class="guide-step"><b>${i+1}</b><p><strong>${s.name} · ${s.duration}s</strong><br>${s.desc}<br><small>${s.camera}</small></p></div>`).join('')}<div class="modal-actions"><button class="btn" data-close>返回修改</button><button class="btn primary" id="confirm-script">确认脚本并进入分镜</button></div>`);$('#confirm-script').onclick=()=>{state.scriptReady=true;state.confirmedScript=scriptKey();persist();closeModal();render();toast('已确认示例脚本，可以创建镜头任务');};}else if(a==='generate-drama'){if(!state.scriptReady||state.confirmedScript!==scriptKey())return toast('请先重新确认当前故事与角色的分镜脚本');enqueue('drama',4);}else if(a==='generate-shot'){if(!state.scriptReady||state.confirmedScript!==scriptKey())return toast('请先重新确认当前故事与角色的分镜脚本');enqueue('drama',1,state.shot);}else if(a==='upload')$('#file-input').click();else if(a==='optimize'){if(!state.prompt.trim())return toast('请先填写创作要求');modal('创作要求优化 · 示例',`<p>原始要求：${esc(state.prompt)}</p><p>建议补充：浅鼠尾草绿背景、柔和侧光；商品瓶身和标签不变；标题区域保留上方约三分之一；避免添加未提供的功效宣称。</p><p>此建议为固定示例，不是 DeepSeek 实时输出。</p><div class="modal-actions"><button class="btn primary" id="apply-prompt">追加到创作要求</button></div>`);$('#apply-prompt').onclick=()=>{state.prompt+='\n浅鼠尾草绿背景，柔和侧光；保留商品瓶身和标签，标题区域留白，不添加未经确认的功效宣称。';persist();closeModal();render();};}else if(a==='undo'){const current=JSON.stringify({title:state.title,textSize:state.textSize,color:state.color,textX:state.textX,textY:state.textY,ratio:state.ratio});let previous;while(history.length){const candidate=history.pop();if(JSON.stringify(candidate)!==current){previous=candidate;break;}}if(!previous)return toast('暂无可撤销的画布编辑');Object.assign(state,previous);persist();render();toast('已撤销上一步画布编辑');}else if(a==='move-info')toast('拖动画布中的标题框即可调整位置');else if(a==='duration-info')toast('演示固定为 4 镜头 × 5 秒，16:9 分镜预览');else if(a==='failure-demo'){failNext=true;toast('下一项开始运行的任务将模拟失败，可创建任务后重试');render();}else if(a==='guide')showGuide();else if(a==='settings')showSettings();else if(a==='export-commerce')exportCommerce();else if(a==='export-drama')exportDrama();else if(a==='backup')backup();else if(a==='preview')preview();}
function enqueue(scenario,n,shot=0){if(activeCount()+n>20)return toast('队列最多保留 20 个待处理任务，请先完成或取消部分任务');const batch=Date.now();for(let i=0;i<n;i++){const snap=scenario==='commerce'?{label:`电商 · ${state.ratio} · ${['晨光植物','奶油极简','暖调胶片'][state.style]}`,prompt:state.prompt,style:state.style,ratio:state.ratio,title:state.title,textSize:state.textSize,color:state.color,textX:state.textX,textY:state.textY,uploadedAssetName:state.assetName,assetId:state.assetId}:{label:`短剧 · ${state.storyTitle} · 镜头 ${n===1?shot+1:i+1}`,story:state.story,title:state.storyTitle,characters:state.characters,scriptKey:state.confirmedScript,shot:n===1?shot:i};state.tasks.push({id:`t-${batch}-${i}-${Math.random().toString(36).slice(2,6)}`,scenario,name:scenario==='commerce'?`商品场景图 · 创意 ${i+1}`:`${state.storyTitle} · 镜头 ${n===1?shot+1:i+1}`,status:'queued',progress:0,snapshot:snap,createdAt:Date.now(),attempt:1});}persist();render();toast(`已加入 ${n} 个模拟任务，可继续编辑或前往任务中心`);}
setInterval(()=>{let changed=false;state.tasks.forEach(t=>{if(t.status==='running'){t.progress=Math.min(100,t.progress+10);changed=true;if(t.progress>=100){if(t.fail){t.status='failed';t.error='模拟服务暂时不可用；此任务未产出结果，可单独重试。';}else{t.status='completed';if(!state.results.some(r=>r.taskId===t.id))state.results.push({taskId:t.id,scenario:t.scenario,name:t.name});}}}});let running=state.tasks.filter(t=>t.status==='running').length;for(const t of state.tasks){if(running>=2)break;if(t.status==='queued'){t.status='running';t.progress=0;t.fail=failNext;if(failNext)failNext=false;running++;changed=true;}}if(changed){persist();refreshTaskUI();}},500);
async function uploadFile(e){
  const input=e.target, f=input.files?.[0];if(!f)return;input.value='';
  if(!['image/png','image/jpeg','image/webp'].includes(f.type))return toast('仅支持 PNG、JPG、WebP 图片');
  if(f.size>2*1024*1024)return toast('演示上传限 2MB，请压缩后再试');
  try{
    const reader=new FileReader();const data=await new Promise((ok,no)=>{reader.onload=()=>ok(reader.result);reader.onerror=no;reader.readAsDataURL(f);});
    const test=new Image();await new Promise((ok,no)=>{test.onload=ok;test.onerror=no;test.src=data;});
    const id='upload-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),previous=state.assetId;
    state.assets[id]={source:data,name:f.name};state.assetId=id;state.assetName=f.name;
    if(previous&&!state.tasks.some(t=>t.snapshot.assetId===previous))delete state.assets[previous];
    persist();render();toast(storageAvailable?'已替换本地素材；不会发送到模型':'素材已加载但本机保存失败，请导出项目备份');
  }catch{toast('图片无法读取，请更换文件');}
}
function modal(title,body){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-close aria-label="关闭弹窗">${icon('close')}</button></div>${body}</section></div>`;$('#modal-root').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();};$('.modal').focus();}
function closeModal(){clearInterval(playTimer);playing=false;$('#modal-root').innerHTML='';}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const els=[...$('.modal').querySelectorAll('button:not(:disabled),a,input,textarea,select,[tabindex="0"]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function showGuide(){modal('5 分钟，走完一次完整创作',`<p>这是一份面试展示用交互原型。线上模型是目标架构，当前不进行模型调用，所有素材与进度均明确标为演示。</p><div class="guide-step"><b>1</b><p><strong>电商素材 · 90 秒</strong><br>切换风格与尺寸，修改标题并拖动位置；创建一组任务，继续编辑，最后下载画布 PNG。</p></div><div class="guide-step"><b>2</b><p><strong>短剧分镜 · 90 秒</strong><br>查看角色设定，生成并确认示例脚本；选择镜头，批量创建任务，预览静帧序列并下载分镜 JSON。</p></div><div class="guide-step"><b>3</b><p><strong>并发与恢复 · 60 秒</strong><br>任务中心最多同时运行两项；点击“模拟一次失败”后创建任务，单独重试失败项。刷新时运行任务标为中断，标题等编辑保留。</p></div><div class="guide-step"><b>4</b><p><strong>方案与取舍 · 60 秒</strong><br>打开方案文档，解释模型职责、两场景共享能力、质量门槛与线上任务架构。</p></div><div class="modal-actions"><button class="btn" id="guide-drama">体验短剧</button><button class="btn primary" id="guide-start">开始电商创作</button></div>`);$('#guide-start').onclick=()=>{state.view='commerce';persist();closeModal();render();};$('#guide-drama').onclick=()=>{state.view='drama';persist();closeModal();render();};}
function showSettings(){modal('线上模型方案与演示边界',`<h3>DeepSeek · 创意与脚本</h3><p>默认规划 deepseek-flash，复杂脚本候选 deepseek-v4-pro；通过服务端调用 https://api.deepseek.com/chat/completions。Flash 图片理解可辅助提取商品信息，识别结果仍需用户确认。</p><h3>视觉生成 · 独立服务</h3><p>方案候选：FLUX.2 图像生成与编辑，Runway Gen-4.5 图生视频。当前均未接入，没有生成费用。</p><h3>此原型已经实现</h3><p>两个场景、标题与画布编辑、素材本地替换、模拟队列与重试、本浏览器保存、PNG 与 JSON 导出。</p><h3>此原型尚未实现</h3><p>线上模型调用、真实视频生成、服务器队列、账号鉴权与跨设备同步。接入时密钥只保存在服务端，不应写入浏览器或代码仓库。</p><p>来源：<a href="https://api-docs.deepseek.com/quick_start/pricing/" target="_blank" rel="noopener noreferrer" style="color:#ceee92">DeepSeek 官方模型说明 ↗</a></p>`);}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(){download(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),kind:'muse-demo-backup',state},null,2)],{type:'application/json'}),'MUSE-项目备份.json');toast('项目快照已导出，可用于留存与核对');}
async function exportCommerce(){
  modal('导出电商素材',`<p>下载当前画布的 PNG，保留当前素材、画面比例、标题样式与位置。</p><div class="export-summary"><div>尺寸<b>${size().join(' × ')}</b></div><div>来源<b>演示合成 · 非模型实测</b></div></div><p>导出含“DEMO”标识。</p><div class="modal-actions"><button class="btn" id="backup-export">项目 JSON</button><button class="btn primary" id="download-png">下载 PNG</button></div>`);
  $('#backup-export').onclick=backup;
  $('#download-png').onclick=async()=>{
    const b=$('#download-png');b.disabled=true;b.textContent='正在导出…';
    try{
      const img=new Image();img.src=currentImage();await img.decode();await document.fonts.ready;
      const [w,h]=size(),c=document.createElement('canvas');c.width=w;c.height=h;
      const ctx=c.getContext('2d'),scale=Math.max(w/img.width,h/img.height);
      ctx.filter=['none','saturate(.45) brightness(1.1)','sepia(.35)'][state.style];
      ctx.drawImage(img,(w-img.width*scale)/2,(h-img.height*scale)/2,img.width*scale,img.height*scale);ctx.filter='none';
      const board=$('#artboard').getBoundingClientRect(),k=w/board.width;
      ctx.save();ctx.scale(k,k);ctx.beginPath();ctx.rect(0,0,board.width,board.height);ctx.clip();
      // Use the browser's actual line layout, including wrapped text and letter spacing.
      for(const el of $('#poster-copy').querySelectorAll('.mini,h2,.desc')){
        const css=getComputedStyle(el);ctx.font=`${css.fontWeight} ${css.fontSize} ${css.fontFamily}`;ctx.fillStyle=css.color;ctx.textBaseline='alphabetic';
        for(const node of el.childNodes){if(node.nodeType!==Node.TEXT_NODE)continue;let offset=0;
          for(const char of node.textContent){const range=document.createRange();range.setStart(node,offset);offset+=char.length;range.setEnd(node,offset);const r=range.getBoundingClientRect();if(!r.width||char==='\n')continue;const m=ctx.measureText(char);ctx.fillText(char,r.left-board.left,r.top-board.top+(m.fontBoundingBoxAscent||parseFloat(css.fontSize)*.85));}
        }
      }
      ctx.restore();ctx.fillStyle='#222b21';ctx.font='14px sans-serif';ctx.textBaseline='alphabetic';ctx.fillText('MUSE STUDIO · DEMO / 预置素材',22,h-25);
      const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('PNG creation failed');
      download(blob,`MUSE-电商创意-${w}x${h}.png`);toast('PNG 已导出');closeModal();
    }catch{if(b.isConnected){b.disabled=false;b.textContent='重试下载 PNG';}toast('导出失败，请确认素材加载完成后重试');}
  };
}
function exportDrama(){modal('导出分镜包',`<p>下载可审阅的分镜 JSON，包含故事梗概、共享角色设定、四镜头脚本、预置素材路径与任务记录。</p><div class="export-summary"><div>分镜规划<b>4 镜头 / 20 秒</b></div><div>交付类型<b>分镜数据 · 非 MP4</b></div></div><p>当前没有视频生成与拼接服务；序列预览是静帧轮播。</p><div class="modal-actions"><button class="btn primary" id="download-story">下载分镜 JSON</button></div>`);$('#download-story').onclick=()=>{download(new Blob([JSON.stringify({project:state.storyTitle,story:state.story,characters:state.characters,presetScript:true,scriptConfirmed:state.scriptReady&&state.confirmedScript===scriptKey(),scriptKey:state.confirmedScript,previewType:'still-image-sequence',videoGenerated:false,shots:scenes.map((s,i)=>({...s,index:i+1,asset:'assets/story.png',assetSource:'preset-demo',tasks:state.tasks.filter(t=>t.scenario==='drama'&&t.snapshot.shot===i&&t.snapshot.scriptKey===state.confirmedScript)}))},null,2)],{type:'application/json'}),'MUSE-短剧分镜.json');closeModal();toast('分镜 JSON 已导出');};}
function preview(){let index=0;playing=true;modal('分镜序列预览 · 静帧演示',`<p>4 镜头 × 5 秒。使用同一预置剧照的裁切视图，没有生成真实视频。</p><div class="storyboard-view" style="margin:0"><img id="preview-img" src="assets/story.png" alt="静帧序列预览"><div class="film-overlay"></div><div id="preview-caption" class="shot-caption">${scenes[0].desc}</div></div><p id="preview-status" style="margin-top:12px">镜头 1 / 4 · ${scenes[0].name}</p><div class="modal-actions"><button class="btn" id="preview-pause">暂停</button></div>`);function tick(){index++;if(index>=4){clearInterval(playTimer);playing=false;$('#preview-status').textContent='预览结束 · 4 / 4';$('#preview-pause').textContent='重新播放';return;}$('#preview-img').style.objectPosition=scenes[index].pos;$('#preview-caption').textContent=scenes[index].desc;$('#preview-status').textContent=`镜头 ${index+1} / 4 · ${scenes[index].name}`;}playTimer=setInterval(tick,5000);$('#preview-pause').onclick=()=>{if(playing){clearInterval(playTimer);playing=false;$('#preview-pause').textContent='继续播放';}else{if(index>=4){index=-1;tick();}playing=true;playTimer=setInterval(tick,5000);$('#preview-pause').textContent='暂停';}};}
function updateStoryInput(){
  state.scriptReady=!!state.confirmedScript&&state.confirmedScript===scriptKey();
  for(const b of document.querySelectorAll('[data-action="generate-drama"],[data-action="generate-shot"]'))b.disabled=!state.scriptReady;
  const b=$('[data-action="generate-script"]');if(b)b.textContent=state.scriptReady?'✧ 重新生成分镜脚本':'✧ 生成分镜脚本';
  if($('#drama-project-title'))$('#drama-project-title').textContent='分镜预览 / '+state.storyTitle;
  if($('#drama-caption-title'))$('#drama-caption-title').textContent=state.storyTitle;
  if($('#drama-characters'))$('#drama-characters').textContent=state.characters;
  const foot=$('.canvas-foot span');if(foot)foot.textContent=state.scriptReady?'✓ 分镜脚本已确认':'输入已变更 · 请重新确认示例脚本';
}
function showTaskResult(t){
  const snap=t.snapshot;
  const body=t.scenario==='commerce'?`<div class="artboard task-result-board" data-ratio="${snap.ratio}" style="margin:0 auto"><img src="${taskImage(t)}" style="filter:${['none','saturate(.45) brightness(1.1)','sepia(.35)'][snap.style||0]}" alt="提交时的素材"><div class="poster-copy" style="left:${snap.textX}%;top:${snap.textY}%;color:${snap.color}"><span class="mini">MUSE · BOTANICAL</span><h2 style="font-size:${snap.textSize}px">${esc(snap.title)}</h2><span class="desc">植物精华液 / 春日限定灵感</span></div></div>`:`<img class="preview-image" src="${taskImage(t)}" alt="预置分镜"><p>${esc(scenes[snap.shot].desc)}</p>`;
  modal('模拟任务结果',body+`<p style="margin-top:15px">${esc(t.name)} · 使用提交时的素材与设置展示，不是线上模型新生成结果。</p><p>素材：${esc(snap.uploadedAssetName||'预置虚构剧照')}；后续编辑不会覆盖此快照。</p>`);
}
function taskActions(t){
  return `${['queued','running'].includes(t.status)?`<button class="btn small" data-cancel="${t.id}">取消</button>`:''}${['failed','interrupted','cancelled'].includes(t.status)?`<button class="btn small" data-retry="${t.id}">重试</button>`:''}${t.status==='completed'?`<button class="btn small" data-open-task="${t.id}">查看结果</button>`:''}<button class="icon-btn" data-snapshot="${t.id}" aria-label="查看任务快照">${icon('eye')}</button>`;
}
function refreshTaskUI(){
  const badge=$('.nav .count');if(badge)badge.textContent=activeCount();
  const resultCount=$('#commerce-result-count');if(resultCount)resultCount.textContent=state.results.filter(r=>r.scenario==='commerce').length+' 张模拟任务结果';
  for(const status of ['running','queued','completed']){const el=$('#'+status+'-count');if(el)el.textContent=state.tasks.filter(t=>t.status===status).length;}
  let rebind=false;
  for(const card of document.querySelectorAll('[data-task-id]')){
    const t=state.tasks.find(t=>t.id===card.dataset.taskId);if(!t)continue;
    const progress=card.querySelector('.progress');progress.classList.toggle('hidden',t.status!=='running');progress.querySelector('i').style.width=t.progress+'%';
    if(card.dataset.status===t.status)continue;
    const oldActions=card.querySelector('.task-actions');const html=taskActions(t);
    const kind=status=>['queued','running'].includes(status)?'cancel':['failed','interrupted','cancelled'].includes(status)?'retry':'result';if(kind(card.dataset.status)!==kind(t.status)){oldActions.innerHTML=html;rebind=true;}
    card.dataset.status=t.status;const label=card.querySelector('.status');label.textContent=statuses[t.status];label.className='status '+t.status;
    const error=card.querySelector('.error');error.textContent=t.error||'';error.classList.toggle('hidden',!t.error);
  }
  const grid=$('#asset-grid');
  if(grid){for(const result of state.results)if(!grid.querySelector(`[data-result-id="${result.taskId}"]`)){grid.insertAdjacentHTML('beforeend',resultAssetCard(result));rebind=true;}}
  if(rebind)bind();
}
function resultAssetCard(result){
  const t=state.tasks.find(t=>t.id===result.taskId);
  return `<article class="asset-card" data-result-id="${result.taskId}"><img src="${t?taskImage(t):'assets/product.png'}" alt="${esc(result.name)}"><div class="body"><h3>${esc(result.name)}</h3><p>模拟任务结果 · ${esc(result.taskId)}</p><div class="inline-tags"><span class="tag">${result.scenario==='commerce'?'电商素材':'短剧分镜'}</span><button class="text-btn" data-open-task="${result.taskId}">查看提交结果 ↗</button></div></div></article>`;
}
persist();render();
